const PIMG={antiaereo:{1:"data:image/webp;base64,",2:"data:image/webp;base64,",3:"data:image/webp;base64,"},arbol:{1:"data:image/webp;base64,"},astillero:{1:"data:image/webp;base64,",2:"data:image/webp;base64,",3:"data:image/webp;base64,"},banco:{1:"data:image/webp;base64,",2:"data:image/webp;base64,",3:"data:image/webp;base64,"},bunker:{1:"data:image/webp;base64,",2:"data:image/webp;base64,",3:"data:image/webp;base64,"},casa:{1:"data:image/webp;base64,",2:"data:image/webp;base64,",3:"data:image/webp;base64,"},central:{1:"data:image/webp;base64,",2:"data:image/webp;base64,",3:"data:image/webp;base64,"},civil:{1:"data:image/webp;base64,",2:"data:image/webp;base64,",3:"data:image/webp;base64,"},costa:{1:"data:image/webp;base64,",2:"data:image/webp;base64,",3:"data:image/webp;base64,"},cuartel:{1:"data:image/webp;base64,",2:"data:image/webp;base64,",3:"data:image/webp;base64,"},escudo:{1:"data:image/webp;base64,",2:"data:image/webp;base64,",3:"data:image/webp;base64,"},estatua:{1:"data:image/webp;base64,"},fabrica:{1:"data:image/webp;base64,",2:"data:image/webp;base64,",3:"data:image/webp;base64,"},forja:{1:"data:image/webp;base64,",2:"data:image/webp;base64,",3:"data:image/webp;base64,"},fuente:{1:"data:image/webp;base64,"},genetico:{1:"data:image/webp;base64,",2:"data:image/webp;base64,",3:"data:image/webp;base64,"},granja:{1:"data:image/webp;base64,",2:"data:image/webp;base64,",3:"data:image/webp;base64,"},hangar:{1:"data:image/webp;base64,",2:"data:image/webp;base64,",3:"data:image/webp;base64,"},hq:{1:"data:image/webp;base64,",2:"data:image/webp;base64,",3:"data:image/webp;base64,"},lab:{1:"data:image/webp;base64,",2:"data:image/webp;base64,",3:"data:image/webp;base64,"},laser:{1:"data:image/webp;base64,",2:"data:image/webp;base64,",3:"data:image/webp;base64,"},llamat:{1:"data:image/webp;base64,",2:"data:image/webp;base64,",3:"data:image/webp;base64,"},mina:{1:"data:image/webp;base64,",2:"data:image/webp;base64,",3:"data:image/webp;base64,"},mortero:{1:"data:image/webp;base64,",2:"data:image/webp;base64,",3:"data:image/webp;base64,"},muro:{1:"data:image/webp;base64,",2:"data:image/webp;base64,",3:"data:image/webp;base64,"},pino:{1:"data:image/webp;base64,"},pozo:{1:"data:image/webp;base64,",2:"data:image/webp;base64,",3:"data:image/webp;base64,"},recolector:{1:"data:image/webp;base64,",2:"data:image/webp;base64,",3:"data:image/webp;base64,"},tesla:{1:"data:image/webp;base64,",2:"data:image/webp;base64,",3:"data:image/webp;base64,"},tfranco:{1:"data:image/webp;base64,",2:"data:image/webp;base64,",3:"data:image/webp;base64,"},torre:{1:"data:image/webp;base64,",2:"data:image/webp;base64,",3:"data:image/webp;base64,"},trampa:{1:"data:image/webp;base64,",2:"data:image/webp;base64,",3:"data:image/webp;base64,"}};
const pimgLv=(k,l)=>{const v=PIMG[k],n=Object.keys(v).length;return v[n>=3?(l<=2?1:l<=5?2:3):Math.min(n,l>=3?2:1)]||v[1]};
const PSC={arbol:.72,pino:.72,fuente:.85,estatua:.85};
const pimgTag=(k,l)=>{const s=PSC[k]||1,im=`<image href="${pimgLv(k,l)}" x="-12.45" y="-2.1" width="125" height="125"/>`;return s===1?im:`<g transform="translate(${50*(1-s)},${120*(1-s)}) scale(${s})">${im}</g>`};
for(const k in PIMG)if(ART[k])ART[k]=lv=>pimgTag(k,lv>=3?6:lv>=2?3:1);
for(let n=1;n<=3;n++)ART['civil'+n]=PIMG.civil?()=>pimgTag('civil',[1,3,6][n-1]):ART.casa;
